/*
 * Single-mode bosonic phase-space
 *
 * Fock-basis representation. Every state is a complex amplitude array c[0 ..
 * n_max] with |\psi> = sum_n c_n |n>. All operations below act directly on that
 * array; there is no operator-algebra helper and no automatic truncation, so
 * is responsible for choosing n_max large enough that discarded tail is
 * negligible (each state builder below rejects inputs whose probability mass
 * would push past its own safety bound)
 *
 * State builders:
 *   ps_fock_state        - a single occupied level
 *   ps_coherent_state    - |\alpha>, generated by recurrence
 *                          c_{n+1} = \alpha c_n / \sqrt(n + 1) starting from
 *                          exact Gaussian prefactor \exp(-|\alpha|^2 / 2),
 *                          then normalised on truncated space
 *   ps_cat_state         - (|\alpha> +- |-\alpha>) / norm, built by taking
 *                          coherent state and keeping only even or only odd n
 *                          (Fock parity of |\alpha> is exactly same parity as
 *                          cat), then normalised
 *   ps_squeezed_vacuum   - S(r \exp(i \theta)) |0>, generated by two-step
 *                          recurrence for even-n amplitudes c_{2m} = c_{2m-2}
 *                          * (-\tanh(r) \exp(i \theta)) * \sqrt((2m - 1) /
 * (2m)) starting from c_0 = 1 / \sqrt(\cosh(r))
 *
 * Kerr evolution (ps_kerr_evolve):
 *   H = \chi n (n - 1) is diagonal in Fock basis, so one step is exact phase
 *   multiplication c_n -> c_n \exp(-i \chi t n (n-1)) integer part of n (n-1)
 *   \chi t is folded mod 2 pi before multiply so phase stays accurate for large
 *   n; this is what makes chi t = pi return state to itself rather than
 *   accumulating round-off
 *
 * Wave function (ps_wavefunction):
 *   \psi(x) = \sum_n c_n \phi_n(x) with Hermite functions \phi_n built by
 *   standard stable three-term recurrence
 *       \phi_{n + 1}(x) = \sqrt(2 / (n + 1)) x \phi_n(x)
 *                        - \sqrt(n/(n + 1)) \phi_{n - 1}(x)
 *   started from \phi_0(x) = \pi^{-1 / 4} \exp(-x^2 / 2)
 *
 * Wigner function (ps_wigner):
 *   W(x, p) = (1 / \pi) \int \psi*(x+y) \psi(x-y) \exp(2 i p y) dy
 *   evaluated on a uniform x grid by a discrete sum over offsets y = k dx
 *   Double complex exponential \cos(2 p_l k dx) + i \sin(2 p_l k dx) is
 *   precomputed once into a table of size np * (nx / 2 + 1), so main loop is a
 *   real multiply-add per (l, j, k) triple. truncation of sum at k = min(j, nx
 *   - 1 - j) reflects wave function's support: |\psi(x_j +- k dx)| is only
 *   nonzero inside grid
 *
 * Negativity (ps_wigner_negativity):
 *   (integral |W| - 1) / 2, phase-space volume of negative part, computed on
 *   same uniform grid by summing |W| and subtracting unit total (W integrates
 * to 1 for any normalised pure state)
 */
#include "phase_space.h"
#include "complex.h"
#include <math.h>
#include <stddef.h>
#include <stdlib.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

int ps_fock_state(complex_t *c, int n_max, int n) {
  if (!c || n_max < 0 || n < 0 || n > n_max) {
    return -1;
  }

  for (int k = 0; k <= n_max; k++) {
    c[k] = c_zero();
  }

  c[n] = c_one();

  return 0;
}

static void normalise(complex_t *c, int n_max) {
  double sum = ps_norm2(c, n_max);

  if (sum > 0.0) {
    double s = 1.0 / sqrt(sum);

    for (int k = 0; k <= n_max; k++) {
      c[k] = c_scale(c[k], s);
    }
  }
}

static int coherent_ok(const complex_t *c, int n_max, double ar, double ai) {
  return c && n_max >= 0 && isfinite(ar) && isfinite(ai) &&
         ar * ar + ai * ai <= 0.5 * n_max;
}

int ps_coherent_state(complex_t *c, int n_max, double alpha_re,
                      double alpha_im) {
  if (!coherent_ok(c, n_max, alpha_re, alpha_im)) {
    return -1;
  }

  complex_t alpha = c_new(alpha_re, alpha_im);

  c[0] = c_real(exp(-0.5 * (alpha_re * alpha_re + alpha_im * alpha_im)));
  for (int n = 1; n <= n_max; n++) {
    c[n] = c_scale(c_mul(c[n - 1], alpha), 1.0 / sqrt((double)n));
  }

  normalise(c, n_max);

  return 0;
}

int ps_cat_state(complex_t *c, int n_max, double alpha_re, double alpha_im,
                 int parity) {
  if (parity != 1 && parity != -1) {
    return -1;
  }

  if (ps_coherent_state(c, n_max, alpha_re, alpha_im) != 0) {
    return -1;
  }

  for (int n = 0; n <= n_max; n++) {
    int keep = (n % 2 == 0) == (parity == 1);

    c[n] = c_scale(c[n], keep ? 2.0 : 0.0);
  }

  normalise(c, n_max);

  return 0;
}

int ps_squeezed_vacuum(complex_t *c, int n_max, double r, double theta) {
  if (!c || n_max < 0 || !isfinite(r) || !isfinite(theta) ||
      sinh(r) * sinh(r) > n_max / 3.0) {
    return -1;
  }

  complex_t f = c_scale(c_from_polar(1.0, theta), -tanh(r));

  for (int n = 0; n <= n_max; n++) {
    c[n] = c_zero();
  }

  c[0] = c_real(1.0 / sqrt(cosh(r)));
  for (int m = 1; 2 * m <= n_max; m++) {
    c[(ptrdiff_t)2 * m] =
        c_scale(c_mul(c[2 * m - 2], f), sqrt((2.0 * m - 1.0) / (2.0 * m)));
  }
  normalise(c, n_max);

  return 0;
}

int ps_kerr_evolve(complex_t *c, int n_max, double chi_t) {
  if (!c || n_max < 0 || !isfinite(chi_t)) {
    return -1;
  }

  for (int n = 0; n <= n_max; n++) {
    // reduce n (n - 1) \chi t modulo 2 \pi through integer part for accuracy
    double nn = (double)n * (n - 1.0);
    double ph = -fmod(nn * chi_t, 2.0 * M_PI);

    c[n] = c_mul(c[n], c_from_polar(1.0, ph));
  }

  return 0;
}

double ps_norm2(const complex_t *c, int n_max) {
  if (!c || n_max < 0) {
    return NAN;
  }

  double sum = 0.0;

  for (int n = 0; n <= n_max; n++) {
    sum += c_abs2(c[n]);
  }

  return sum;
}

double ps_mean_photon_number(const complex_t *c, int n_max) {
  if (!c || n_max < 0) {
    return NAN;
  }

  double sum = 0.0;

  for (int n = 0; n <= n_max; n++) {
    sum += n * c_abs2(c[n]);
  }

  return sum;
}

int ps_wavefunction(const complex_t *c, int n_max, const double *x, int nx,
                    complex_t *psi) {
  if (!c || !x || !psi || n_max < 0 || nx < 1) {
    return -1;
  }

  for (int j = 0; j < nx; j++) {
    double xj = x[j], prev = 0.0, cur = pow(M_PI, -0.25) * exp(-0.5 * xj * xj);
    complex_t sum = c_scale(c[0], cur);

    for (int n = 0; n < n_max; n++) {
      double next =
          sqrt(2.0 / (n + 1.0)) * xj * cur - sqrt((double)n / (n + 1.0)) * prev;

      prev = cur;
      cur = next;
      sum = c_add(sum, c_scale(c[n + 1], cur));
    }

    psi[j] = sum;
  }

  return 0;
}

int ps_wigner(const complex_t *psi, int nx, double dx, const double *p, int np,
              double *W) {
  if (!psi || !p || !W || nx < 1 || np < 1 || !(dx > 0.0)) {
    return -1;
  }

  int half = nx / 2 + 1;
  double *cs = malloc((size_t)np * half * 2 * sizeof *cs);

  if (!cs) {
    return -1;
  }

  for (int l = 0; l < np; l++) {
    for (int k = 0; k < half; k++) {
      double ph = 2.0 * p[l] * k * dx;

      cs[((size_t)l * half + k) * 2] = cos(ph);
      cs[((size_t)l * half + k) * 2 + 1] = sin(ph);
    }
  }

  for (int j = 0; j < nx; j++) {
    int kmax = j < nx - 1 - j ? j : nx - 1 - j;
    double d0 = c_abs2(psi[j]);

    for (int l = 0; l < np; l++) {
      double sum = d0;
      const double *t = cs + (size_t)l * half * 2;

      for (int k = 1; k <= kmax; k++) {
        complex_t a = c_mul(c_conj(psi[j + k]), psi[j - k]);

        sum += 2.0 * (a.re * t[(ptrdiff_t)2 * k] - a.im * t[2 * k + 1]);
      }

      W[(size_t)l * nx + j] = sum * dx / M_PI;
    }
  }
  
  free(cs);

  return 0;
}

double ps_wigner_negativity(const double *W, int nx, int np, double dx,
                            double dp) {
  if (!W || nx < 1 || np < 1 || !(dx > 0.0) || !(dp > 0.0)) {
    return NAN;
  }

  double sum = 0.0;

  for (size_t i = 0; i < (size_t)nx * np; i++) {
    sum += fabs(W[i]);
  }

  return 0.5 * (sum * dx * dp - 1.0);
}
